WFJ.Data.add("spell", {
  [429125] = { "Accelera il lancio d'incantesimi, aumentando la velocità di lancio del $N1% e riducendo del $N2% il ritardo subito dagli attacchi dannosi durante il lancio. Dura $D1.", "Velocità di lancio di tutti gli incantesimi aumentata del $N1% e ritardi di lancio causati dagli attacchi che infliggono danni ridotti del $N2%.", 0xa582f7cd, 0xf27759c8, "uu" },
  [429133] = { "Aumenta del $N1% i danni prevenuti dalla tua Blessing of Sanctuary e aumenta i danni inflitti dalla tua Blessing of Sanctuary del $N2% del tuo indice di blocco con lo scudo.", nil, 0x209165ce, nil, "um" },
  [429139] = { "I danni della tua Consacrazione ora possono essere critici, e i danni dei tuoi incantesimi Esorcismo, ⟦Holy Shock=Folgore Sacra⟧, Luce Solare, ⟦Holy Wrath=Ira Sacra⟧ e Consacrazione ottengono una probabilità di critico aggiuntiva pari alla tua probabilità di critico in mischia.", nil, 0x32d40b31, nil, "um" },
  [429142] = { "Aumenta del $N1% la tua probabilità di critico con gli incantesimi. Inoltre, i tuoi incantesimi di cura critici curano il bersaglio del $N2% della quantità curata in $D1.", nil, 0x0f4bf44b, nil, "um" },
  [429144] = { "Riduce del $N1% il costo in mana dei tuoi incantesimi Purificazione e Depurazione e riduce del $N2% il tempo di recupero dei tuoi incantesimi Esorcismo e ⟦Holy Wrath=Ira Sacra⟧.", nil, 0x427809ff, nil, "um" },
  [429145] = { "Scaglia dardi di potere sacro in tutte le direzioni, infliggendo $N1 danni da sacro a tutti i bersagli entro $N2 metri e stordendo per $D1 i bersagli Demoni e Non Morti.", nil, 0x81ff6833, nil, "um" },
  [429146] = { "Scaglia dardi di potere sacro in tutte le direzioni, infliggendo $N1 danni da sacro a tutti i bersagli entro $N2 metri e stordendo per $D1 i bersagli Demoni e Non Morti.", nil, 0x81ff6833, nil, "um" },
  [429147] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [429151] = { "Scaglia un martello che colpisce un nemico infliggendo $N1 danni da sacro. Utilizzabile solo sui nemici con il $N2% di salute o meno.", nil, 0xd7d2c907, nil, "um" },
  [429152] = { "⟦Hammer of Wrath=Martello dell'Ira⟧ ora è istantaneo e il suo tempo di recupero si azzera ogni volta che danneggia un nemico con meno del $N1% di salute.", nil, 0x7de718d6, nil, "um" },
  [429242] = { "Incidi sui tuoi bracciali la runa Grazia della Luce:\n\n$I1\nIl tuo incantesimo Luce Sacra riduce di $D1 il tempo di lancio del tuo prossimo incantesimo Luce Sacra. Dura $D2.", nil, 0xc71d8de2, nil, "um" },
  [429243] = { "Ottieni l'abilità Grazia della Luce:\n\n$I1\nIl tuo incantesimo Luce Sacra riduce di $D1 il tempo di lancio del tuo prossimo incantesimo Luce Sacra. Dura $D2.", nil, 0xe2a5703d, nil, "um" },
  [429245] = { "Ottieni l'abilità Improved Sanctuary:\n\n$I1\nAumenta del $N1% i danni prevenuti dalla tua Blessing of Sanctuary e aumenta i danni inflitti dalla tua Blessing of Sanctuary del $N2% del tuo indice di blocco con lo scudo.", nil, 0xbbf11e4c, nil, "um" },
  [429247] = { "Incidi sul tuo elmo la runa Improved Sanctuary:\n\n$I1\nAumenta del $N1% i danni prevenuti dalla tua Blessing of Sanctuary e aumenta i danni inflitti dalla tua Blessing of Sanctuary del $N2% del tuo indice di blocco con lo scudo.", nil, 0x58782ca0, nil, "um" },
  [429248] = { "Ottieni l'abilità Wrath:\n\n$I1\nI danni della tua Consacrazione ora possono essere critici, e i danni dei tuoi incantesimi Esorcismo, Folgore Sacra, Luce Solare, Ira Sacra e Consacrazione ottengono una probabilità di critico aggiuntiva pari alla tua probabilità di critico in mischia.", nil, 0x94927efc, nil, "um" },
  [429249] = { "Incidi sul tuo elmo la runa Wrath:\n\n$I1\nI danni della tua Consacrazione ora possono essere critici, e i danni dei tuoi incantesimi Esorcismo, Folgore Sacra, Luce Solare, Ira Sacra e Consacrazione ottengono una probabilità di critico aggiuntiva pari alla tua probabilità di critico in mischia.", nil, 0x561fc040, nil, "um" },
  [429250] = { "Ottieni l'abilità Fanatismo:\n\n$I1\nAumenta del $N1% la tua probabilità di critico con gli incantesimi. Inoltre, i tuoi incantesimi di cura critici curano il bersaglio del $N2% della quantità curata in $D1.", nil, 0x13e5fa0b, nil, "um" },
  [429251] = { "Incidi sul tuo elmo la runa Fanatismo:\n\n$I1\nAumenta del $N1% la tua probabilità di critico con gli incantesimi. Inoltre, i tuoi incantesimi di cura critici curano il bersaglio del $N2% della quantità curata in $D1.", nil, 0x3e638f20, nil, "um" },
  [429254] = { "Ottieni l'abilità Purifying Power:\n\n$I1\nRiduce del $N1% il costo in mana dei tuoi incantesimi Purificazione e Depurazione e riduce del $N2% il tempo di recupero dei tuoi incantesimi Esorcismo e Ira Sacra.", nil, 0x9769f25c, nil, "um" },
  [429255] = { "Incidi sui tuoi bracciali la runa Purifying Power:\n\n$I1\nRiduce del $N1% il costo in mana dei tuoi incantesimi Purificazione e Depurazione e riduce del $N2% il tempo di recupero dei tuoi incantesimi Esorcismo e Ira Sacra.", nil, 0x90f0bff6, nil, "um" },
  [429259] = { "Ottieni l'abilità ⟦Hammer of Wrath=Martello dell'Ira⟧ Migliorato:\n\n$I1\n⟦Hammer of Wrath=Martello dell'Ira⟧ ora è istantaneo e il suo tempo di recupero si azzera ogni volta che danneggia un nemico con meno del $N1% di salute.", nil, 0xfff4bf8a, nil, "um" },
  [429261] = { "Incidi sui tuoi bracciali la runa ⟦Hammer of Wrath=Martello dell'Ira⟧:\n\n$I1\n⟦Hammer of Wrath=Martello dell'Ira⟧ ora è istantaneo e il suo tempo di recupero si azzera ogni volta che danneggia un nemico con meno del $N1% di salute.", nil, 0xd1838ce5, nil, "um" },
  [429283] = { "Ottieni l'abilità Pandemia:\n\n$I1\nAumenta del $N1% il bonus ai danni critici di Corruzione, Bane of Agony, Anatema della Rovina, Risucchio d'Anima, Risucchio di Vita, Aspirazione della Vita e Distruzione.", nil, 0xad528115, nil, "um" },
  [429303] = { "Ottieni l'abilità Gelo Profondo:\n\n$I1\nStordisce il bersaglio per $D1. Utilizzabile solo su bersagli congelati. Infligge $N2 danni ai bersagli immuni in modo permanente allo stordimento. Questi danni beneficiano delle applicazioni di Glaciazione, senza consumarle.", nil, 0xd3f53482, nil, "um" },
  [429304] = { "Incidi sul tuo elmo la runa Gelo Profondo:\n\n$I1\nStordisce il bersaglio per $D1. Utilizzabile solo su bersagli congelati. Infligge $N2 danni ai bersagli immuni in modo permanente allo stordimento. Questi danni beneficiano delle applicazioni di Glaciazione, senza consumarle.", nil, 0xee3fd969, nil, "um" },
  [429305] = { "Ottieni l'abilità Anomalia Temporale:\n\n$I1\nLancia un globo di energia temporale che avanza lentamente e ogni $D1 fornisce a tutti i membri del gruppo vicini uno scudo che assorbe $N2 danni per $D2. Lo scudo accumula valore aggiuntivo se i membri del gruppo restano vicino al globo.", nil, 0x950f9c71, nil, "um" },
  [429306] = { "Incidi sul tuo elmo la runa Anomalia Temporale:\n\n$I1\nLancia un globo di energia temporale che avanza lentamente e ogni $D1 fornisce a tutti i membri del gruppo vicini uno scudo che assorbe $N2 danni per $D2. Lo scudo accumula valore aggiuntivo se i membri del gruppo restano vicino al globo.", nil, 0x463a9f72, nil, "um" },
  [429307] = { "Ottieni l'abilità Armatura Lavica:\n\n$I1\nInfligge $N1 danni da fuoco quando vieni colpito, aumenta del $N2% la tua probabilità di critico con gli incantesimi e riduce del $N3% la probabilità di subire colpi critici. Sul Mago può essere attivo un solo tipo di incantesimo di armatura alla volta. Dura $D1.", nil, 0xa5a12b27, nil, "um" },
  [429308] = { "Incidi sui tuoi bracciali la runa Armatura Lavica:\n\n$I1\nInfligge $N1 danni da fuoco quando vieni colpito, aumenta del $N2% la tua probabilità di critico con gli incantesimi e riduce del $N3% la probabilità di subire colpi critici. Sul Mago può essere attivo un solo tipo di incantesimo di armatura alla volta. Dura $D1.", nil, 0x4406c7f1, nil, "um" },
  [429309] = { "Incidi sui tuoi bracciali la runa Dislocazione:\n\n$I1\nTi teletrasporta nel punto in cui hai lanciato Traslazione l'ultima volta e azzera il tempo di recupero di Traslazione. Utilizzabile solo entro $D1 dal lancio di Traslazione.", nil, 0x19928642, nil, "um" },
  [429310] = { "Ottieni l'abilità Balefire Bolt:\n\n$I1\nScatena contro il nemico un'esplosione di magia pura che distorce la realtà, infliggendo $N1 danni chimerici.\n\nAumenta del $N2% i danni di Balefire Bolt e Pirosfera e riduce del $N3% il tuo Spirito, effetto cumulabile fino a $N4 volte per $D1. Se il tuo Spirito scende a $N6, muori.\n\nQuesto incantesimo viene confrontato con la più bassa tra le resistenze del bersaglio all'arcano, al fuoco e al gelo.", nil, 0x4a4f1ae7, nil, "um" },
  [429311] = { "Incidi sui tuoi bracciali la runa Balefire Bolt:\n\n$I1\nScatena contro il nemico un'esplosione di magia pura che distorce la realtà, infliggendo $N1 danni chimerici.\n\nAumenta del $N2% i danni di Balefire Bolt e Pirosfera e riduce del $N3% il tuo Spirito, effetto cumulabile fino a $N4 volte per $D1. Se il tuo Spirito scende a $N6, muori.\n\nQuesto incantesimo viene confrontato con la più bassa tra le resistenze del bersaglio all'arcano, al fuoco e al gelo.", nil, 0x3f054c1a, nil, "um" },
  [429339] = { "Protegge chi lo porta dagli effetti di Oscurità Devastante.", nil, 0xd0dc6bd9, nil, "um" },
  [429347] = { "Tenta di usare una potente fonte della Luce per distruggere The Box.", "Hai distrutto The Box. Dovresti provare sollievo, ma senti un certo disagio. È come se qualcuno ti stesse osservando.", 0xcc06a1c6, 0xdd2d7419, "uu" },
  [429350] = { "Tenta di contrastare il Vuoto con la Luce e di distruggere The Box.", nil, 0x6b9a9054, nil, "um" },
  [429394] = { nil, "Le ombre acquatiche ti trascinano.", nil, 0xfa3e7545, "mu" },
  [429407] = { nil, "Il cuore e la mente ti pesano di dubbi: senti l'oscurità diffondersi dentro di te.", nil, 0xb4a12121, "mu" },
  [429432] = { nil, "Gli alleati entro $N1 m dalla ⟦Priestess of the Moon=Sacerdotessa della Luna⟧ ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Keeper of the Grove vivo nel suo esercito.", nil, 0x270bb4b9, "mu" },
  [429434] = { "Lancia un dardo di magia oscura contro un bersaglio nemico, infliggendo danni da ombra.", nil, 0x42ce8448, nil, "um" },
  [429436] = { nil, "Gli alleati entro $N1 m dalla ⟦Priestess of the Moon=Sacerdotessa della Luna⟧ ottengono il $N2% di salute in più e il $N3% di danni in più per ogni Keeper of the Grove vivo nel suo esercito.", nil, 0x270bb4b9, "mu" },
  [429541] = { nil, "Tutti i danni subiti ridotti del $N1%.", nil, 0xbd0656aa, "mu" },
