  [429748] = { "Sostituisce la tua abilità ⟦Heroic Strike=Assalto Eroico⟧ con Assalto Lampo:\n\n$I1\nUn attacco in mischia istantaneo e sconsiderato con l'arma a due mani che infligge $N1 danni fisici. Questa abilità beneficia di tutti gli effetti associati ad ⟦Heroic Strike=Assalto Eroico⟧ e li attiva.", nil, 0xcc47287c, nil, "um" },
  [429765] = { "Un attacco in mischia istantaneo e sconsiderato con l'arma a due mani che infligge $N1 danni fisici. Questa abilità beneficia di tutti gli effetti associati ad ⟦Heroic Strike=Assalto Eroico⟧ e li attiva.", nil, 0xb7bd959a, nil, "um" },
